  Definition pm_find_m1 := pm_find_gen (hc_find_nt HConstsU1.hc) O_M1 c_m1 (cu_find_ext _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ CL) (fun w A M model c X => x_m1 X).
