  Lemma pm_spec_lookup : forall (w : pmw MI ST) A M model c (fx : FPState) R (op ret : Z) K,
    PMX w A M model c ->
    getr R 10%bv = Z_to_bv 64 (w_p w) -> getr R 11%bv = Z_to_bv 64 op -> 0 <= op < 2 ^ 31 ->
    getr R 2%bv = Z_to_bv 64 (w_sp w) ->
    getr R 1%bv = Z_to_bv 64 ret -> ret_ok (Z_to_bv 64 ret) ->
    (forall R' M' (r : Z), kept R R' -> getr R' 10%bv = Z_to_bv 64 r -> 0 <= r < 2 ^ 64 ->
        (r = 0 <-> g_specop G op = true) ->
        PMX w A M' model c -> CRep.agree_on (fun a => w_sp w <= a < w_sp0 w) M M' ->
        srealizes SEGS (cfg fx R' ret M' model) K) ->
    srealizes SEGS (cfg fx R (tc_spec_lookup tcU1) M model) K.
